import { parse, type Font } from "opentype.js";
import { forwardRef, useEffect, useId, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// Each letter tracing its outer contours, then its counters, then filling
// from the bottom up. Frames on the 30 fps scene timeline, after `speed`.
// The ids are public: a saved `timing` prop refers to them.

type OutlineTraceElementId = `letter:${number}`;

interface OutlineTraceTimingProps {
  text?: string;
  stagger?: number;
}

const DEFAULT_TEXT = "Outline";
const DEFAULT_STAGGER = 3;

/** Per-letter beats on the 30 fps clock, relative to the letter's start. */
const TRACE_BEATS = {
  outer: [0, 18],
  counter: [4, 18],
  fill: [14, 26],
} as const;

function finite(value: number | undefined, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

// `letter:<i>` is the character at index `i` of `text`, spaces included;
// the letters are a chain. It lasts until it has filled. Its beats, from its
// start: `outer` (the outer contours finish), `counter` and `counterEnd`
// (the counters trace) and `fill` (the fill starts rising).
const outlineTraceTimeline = defineTimeline<
  OutlineTraceElementId,
  OutlineTraceTimingProps
>(({ text = DEFAULT_TEXT, stagger = DEFAULT_STAGGER }) => {
  const step = Math.max(0, finite(stagger, 3));
  const { outer, counter, fill } = TRACE_BEATS;
  return Array.from(text).map(
    (char, i): TimelineElement<OutlineTraceElementId> => ({
      id: `letter:${i}`,
      lane: "Letters",
      label: char,
      start: i * step,
      length: fill[1],
      follows: i > 0 ? `letter:${i - 1}` : undefined,
      beats: {
        outer: outer[1],
        counter: counter[0],
        counterEnd: counter[1],
        fill: fill[0],
      },
    }),
  );
});

interface OutlineTraceProps {
  text?: string;
  fontUrl?: string;
  fontSize?: number;
  color?: string;
  strokeColor?: string;
  strokeWidth?: number;
  stagger?: number;
  fill?: boolean;
  keepStroke?: boolean;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches single letters, by the ids in `./timeline`.
   * Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<OutlineTraceElementId>;
}

/** Static Inter ExtraBold (800) from Google Fonts. */
const interExtraBoldTtf =
  "https://fonts.gstatic.com/s/inter/v20/UcCO3FwrK3iLTeHuS_nVMrMxCp50SjIw2boKoduKmMEVuDyYMZg.ttf";

const outlineTraceDefaults = {
  text: DEFAULT_TEXT,
  fontUrl: interExtraBoldTtf,
  fontSize: 150,
  color: "#fafafa",
  strokeColor: "",
  strokeWidth: 2.5,
  stagger: DEFAULT_STAGGER,
  fill: true,
  keepStroke: false,
  speed: 1,
} satisfies Required<Omit<OutlineTraceProps, "className" | "timing">>;

/** Per-letter beats on the 30 fps clock, relative to the letter's start. */
const outlineTraceTiming = TRACE_BEATS;

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const easeInOutCubic = Easing.inOut(Easing.cubic);
const easeOutCubic = Easing.out(Easing.cubic);

/** Maps a composition frame onto the 30 fps timeline, scaled by `speed`. */
function getOutlineTraceTime(
  frame: number,
  options: { fps?: number; speed?: number } = {},
) {
  const fps = Math.max(1, finite(options.fps, 30));
  const speed = Math.max(0, finite(options.speed, 1));
  return (Math.max(0, finite(frame, 0)) * 30 * speed) / fps;
}

interface OutlineTraceLetterState {
  /** Trim progress of the outer contours, 0..1. */
  outer: number;
  /** Trim progress of the counters, 0..1. */
  counter: number;
  /** Share of the glyph box the fill has risen through, 0..1. */
  fill: number;
}

/**
 * A letter's state at `t`. Pass the letter's resolved element from
 * `./timeline` to follow a `timing` override; without it the letter runs on
 * the default beats, `index * stagger` in.
 */
function getOutlineTraceLetter(
  t: number,
  index: number,
  stagger = outlineTraceDefaults.stagger,
  element?: ResolvedElement<OutlineTraceElementId>,
): OutlineTraceLetterState {
  const { outer, counter, fill } = outlineTraceTiming;
  if (element) {
    const u = t - element.start;
    return {
      outer: interpolate(u, [outer[0], element.beat("outer")], [0, 1], {
        ...CLAMP,
        easing: easeInOutCubic,
      }),
      counter: interpolate(
        u,
        [element.beat("counter"), element.beat("counterEnd")],
        [0, 1],
        { ...CLAMP, easing: easeInOutCubic },
      ),
      fill: interpolate(u, [element.beat("fill"), element.length], [0, 1], {
        ...CLAMP,
        easing: easeOutCubic,
      }),
    };
  }
  const u = t - index * Math.max(0, finite(stagger, 3));
  return {
    outer: interpolate(u, [...outer], [0, 1], {
      ...CLAMP,
      easing: easeInOutCubic,
    }),
    counter: interpolate(u, [...counter], [0, 1], {
      ...CLAMP,
      easing: easeInOutCubic,
    }),
    fill: interpolate(u, [...fill], [0, 1], { ...CLAMP, easing: easeOutCubic }),
  };
}

/** Frame where the last of `count` letters has filled. */
function getOutlineTraceLength(
  count: number,
  stagger = outlineTraceDefaults.stagger,
) {
  const last = Math.max(0, count - 1) * Math.max(0, finite(stagger, 3));
  return Math.ceil(last + outlineTraceTiming.fill[1]);
}

interface PathCommand {
  type: string;
  x?: number;
  y?: number;
  x1?: number;
  y1?: number;
  x2?: number;
  y2?: number;
}

interface Box {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
}

interface OutlineContour {
  d: string;
  box: Box;
  /** True for a hole inside another contour of the same glyph. */
  counter: boolean;
}

const fmt = (n: number) => Number(n.toFixed(2));

/**
 * Splits glyph path commands into closed contours and marks the counters:
 * contours whose box lies inside another contour's box.
 */
function getOutlineContours(commands: readonly PathCommand[]) {
  const raw: { d: string; box: Box }[] = [];
  let d = "";
  let box: Box | null = null;
  const grow = (x = 0, y = 0) => {
    if (!box) box = { x0: x, y0: y, x1: x, y1: y };
    else {
      box.x0 = Math.min(box.x0, x);
      box.y0 = Math.min(box.y0, y);
      box.x1 = Math.max(box.x1, x);
      box.y1 = Math.max(box.y1, y);
    }
  };
  const close = () => {
    if (d && box) raw.push({ d: `${d}Z`, box });
    d = "";
    box = null;
  };
  for (const c of commands) {
    if (c.type === "M") {
      close();
      d = `M${fmt(c.x ?? 0)} ${fmt(c.y ?? 0)}`;
      grow(c.x, c.y);
    } else if (c.type === "L") {
      d += `L${fmt(c.x ?? 0)} ${fmt(c.y ?? 0)}`;
      grow(c.x, c.y);
    } else if (c.type === "Q") {
      d += `Q${fmt(c.x1 ?? 0)} ${fmt(c.y1 ?? 0)} ${fmt(c.x ?? 0)} ${fmt(c.y ?? 0)}`;
      grow(c.x1, c.y1);
      grow(c.x, c.y);
    } else if (c.type === "C") {
      d += `C${fmt(c.x1 ?? 0)} ${fmt(c.y1 ?? 0)} ${fmt(c.x2 ?? 0)} ${fmt(c.y2 ?? 0)} ${fmt(c.x ?? 0)} ${fmt(c.y ?? 0)}`;
      grow(c.x1, c.y1);
      grow(c.x2, c.y2);
      grow(c.x, c.y);
    } else if (c.type === "Z") {
      close();
    }
  }
  close();
  const inside = (a: Box, b: Box) =>
    a !== b && a.x0 >= b.x0 && a.y0 >= b.y0 && a.x1 <= b.x1 && a.y1 <= b.y1;
  return raw.map(
    (c): OutlineContour => ({
      ...c,
      counter: raw.some((other) => inside(c.box, other.box)),
    }),
  );
}

interface OutlineGlyph {
  contours: OutlineContour[];
  box: Box | null;
}

/**
 * Lays out `text` in reference px with the baseline at y = 0. Glyphs are
 * looked up per character: full shaping runs GSUB lookups that opentype.js
 * does not support in every font.
 */
function layoutOutlineGlyphs(
  font: Font,
  text: string,
  fontSize: number,
) {
  const scale = fontSize / font.unitsPerEm;
  const glyphs = Array.from(text).map((char) => font.charToGlyph(char));
  let x = 0;
  const letters: OutlineGlyph[] = glyphs.map((glyph, i) => {
    if (i > 0) x += font.getKerningValue(glyphs[i - 1], glyph) * scale;
    const contours = getOutlineContours(glyph.getPath(x, 0, fontSize).commands);
    x += (glyph.advanceWidth ?? 0) * scale;
    const box = contours.reduce<Box | null>(
      (acc, c) =>
        acc
          ? {
              x0: Math.min(acc.x0, c.box.x0),
              y0: Math.min(acc.y0, c.box.y0),
              x1: Math.max(acc.x1, c.box.x1),
              y1: Math.max(acc.y1, c.box.y1),
            }
          : { ...c.box },
      null,
    );
    return { contours, box };
  });
  const os2 = font.tables.os2 as { sCapHeight?: number } | undefined;
  const capHeight =
    ((os2?.sCapHeight ?? font.unitsPerEm * 0.7) * fontSize) / font.unitsPerEm;
  return { letters, width: x, capHeight };
}

const fontCache = new Map<string, Promise<Font>>();

function loadOutlineFont(url: string) {
  let pending = fontCache.get(url);
  if (!pending) {
    pending = fetch(url)
      .then((res) => res.arrayBuffer())
      .then((buffer) => parse(buffer));
    fontCache.set(url, pending);
    pending.catch(() => fontCache.delete(url));
  }
  return pending;
}

function useOutlineFont(url: string) {
  const [font, setFont] = useState<Font | null>(null);

  useEffect(() => {
    const handle = delayRender(`outline-trace: loading ${url}`);
    let released = false;
    const release = () => {
      if (released) return;
      released = true;
      continueRender(handle);
    };
    loadOutlineFont(url).then((parsed) => {
      if (!released) setFont(parsed);
      release();
    }, release);
    return release;
  }, [url]);

  return font;
}

function OutlineTraceBase(props: OutlineTraceProps) {
  const {
    text = outlineTraceDefaults.text,
    fontUrl = outlineTraceDefaults.fontUrl,
    fontSize = outlineTraceDefaults.fontSize,
    color = outlineTraceDefaults.color,
    strokeColor = outlineTraceDefaults.strokeColor,
    strokeWidth = outlineTraceDefaults.strokeWidth,
    stagger = outlineTraceDefaults.stagger,
    fill = outlineTraceDefaults.fill,
    keepStroke = outlineTraceDefaults.keepStroke,
    speed = outlineTraceDefaults.speed,
    className,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { fps, width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    outlineTraceTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const id = `outline-trace-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const font = useOutlineFont(fontUrl);
  if (!font) return null;

  const unit = height / 720;
  const t = getOutlineTraceTime(frame, { fps, speed });
  const layout = layoutOutlineGlyphs(font, text, fontSize);
  const originX = (width - layout.width * unit) / 2;
  const baseline = (height + layout.capHeight * unit) / 2;
  const stroke = strokeColor || color;

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, overflow: "hidden" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        style={{ display: "block" }}
      >
        <g transform={`translate(${originX} ${baseline}) scale(${unit})`}>
          <filter id={`${id}-erode`}>
            <feMorphology operator="erode" radius={strokeWidth / 2} />
          </filter>
          {layout.letters.map((letter, i) => {
            if (!letter.box) return null;
            const state = getOutlineTraceLetter(
              t,
              i,
              stagger,
              tl.get(`letter:${i}`),
            );
            const box = letter.box;
            const tall = box.y1 - box.y0 + 2 * strokeWidth;
            const rise = tall * (fill ? state.fill : 0);
            const strokeOpacity = fill && !keepStroke ? 1 - state.fill : 1;
            const whole = letter.contours.map((c) => c.d).join("");
            const margin = 4 * strokeWidth;
            return (
              <g key={i}>
                {/* Static instances of variable fonts keep overlapping
                    contours (the bar of a t crosses its stem). The mask hides
                    stroke that runs inside the glyph's filled silhouette. */}
                <mask
                  id={`${id}-mask-${i}`}
                  maskUnits="userSpaceOnUse"
                  x={box.x0 - margin}
                  y={box.y0 - margin}
                  width={box.x1 - box.x0 + 2 * margin}
                  height={box.y1 - box.y0 + 2 * margin}
                >
                  <rect
                    x={box.x0 - margin}
                    y={box.y0 - margin}
                    width={box.x1 - box.x0 + 2 * margin}
                    height={box.y1 - box.y0 + 2 * margin}
                    fill="#ffffff"
                  />
                  <path d={whole} fill="#000000" filter={`url(#${id}-erode)`} />
                </mask>
                {fill && state.fill > 0 ? (
                  <>
                    <clipPath id={`${id}-${i}`}>
                      <rect
                        x={box.x0 - strokeWidth}
                        y={box.y1 + strokeWidth - rise}
                        width={box.x1 - box.x0 + 2 * strokeWidth}
                        height={rise}
                      />
                    </clipPath>
                    <path
                      d={whole}
                      fill={color}
                      clipPath={`url(#${id}-${i})`}
                    />
                  </>
                ) : null}
                {strokeOpacity > 0 ? (
                  <g mask={`url(#${id}-mask-${i})`}>
                    {letter.contours.map((contour, k) => {
                      const progress = contour.counter
                        ? state.counter
                        : state.outer;
                      if (progress <= 0) return null;
                      return (
                        <path
                          key={k}
                          d={contour.d}
                          pathLength={1}
                          fill="none"
                          stroke={stroke}
                          strokeWidth={strokeWidth}
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeDasharray="1 1"
                          strokeDashoffset={1 - progress}
                          opacity={strokeOpacity}
                        />
                      );
                    })}
                  </g>
                ) : null}
              </g>
            );
          })}
        </g>
      </svg>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Outline",
