  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","color","strokeColor","fontSize","strokeWidth","stagger","fill","keepStroke","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Outline",
  color: "#111111",
  strokeColor: "#111111",
  fontSize: 150,
  strokeWidth: 2.5,
  stagger: 3,
  fill: true,
  keepStroke: false,
  speed: 1,
};

type OutlineTraceElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof OutlineTraceBase>;

const OutlineTraceInner = forwardRef<
  HTMLDivElement,
  OutlineTraceElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<OutlineTrace>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <OutlineTraceBase
          {...(componentProps as unknown as ComponentProps<typeof OutlineTraceBase>)}
        />
      </div>
    </Sequence>
  );
});

export const OutlineTrace = Interactive.withSchema({
  Component: OutlineTraceInner,
  componentName: "<OutlineTrace>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
